#!/bin/sh
# Regenerates the SPIR-V of Ycode's own depth shaders (specs/simulator/xr-depth.md):
#   Sources/CYcodeXRReprojection/shaders/*.{vert,frag} -> Sources/CYcodeXRReprojection/reproject_spv.h
#   Sources/YcodeVulkan/shaders/depth_tap.comp          -> Sources/YcodeVulkan/DepthTapShader.swift
# Needs glslc (shaderc, Apache-2.0) on the PATH; the generated files are committed,
# so ordinary builds need no shader compiler. Run from ycode/.
set -e
cd "$(dirname "$0")/.."
command -v glslc >/dev/null || { echo "xr-depth-shaders: glslc not found" >&2; exit 69; }
T=$(mktemp -d)
trap 'rm -rf "$T"' EXIT
S=Sources/CYcodeXRReprojection/shaders
glslc -O --target-env=vulkan1.1 -o "$T/vert.spv" "$S/reproject.vert"
glslc -O --target-env=vulkan1.1 -o "$T/frag.spv" "$S/reproject.frag"
glslc -O --target-env=vulkan1.1 -DCACHE -o "$T/cache.spv" "$S/reproject.frag"
glslc -O --target-env=vulkan1.1 -o "$T/yuvv.spv" "$S/yuv.vert"
glslc -O --target-env=vulkan1.1 -o "$T/yuvf.spv" "$S/yuv.frag"
glslc -O --target-env=vulkan1.2 -o "$T/tap.spv" Sources/YcodeVulkan/shaders/depth_tap.comp
python3 -I - "$T" <<'EOF'
import sys, struct
t = sys.argv[1]
def words(name):
    b = open(f"{t}/{name}", "rb").read()
    return struct.unpack(f"<{len(b)//4}I", b)
def c_array(name, w):
    lines = [f"static const uint32_t {name}[{len(w)}] = {{"]
    for i in range(0, len(w), 8):
        lines.append("    " + ", ".join(f"0x{x:08x}u" for x in w[i:i+8]) + ",")
    lines.append("};")
    return "\n".join(lines)
with open("Sources/CYcodeXRReprojection/reproject_spv.h", "w") as f:
    f.write("/* Generated by scripts/xr-depth-shaders.sh from shaders/reproject.{vert,frag} (frag twice: with CACHE) and shaders/yuv.{vert,frag}\n"
            " * (Ycode's own GLSL, compiled with glslc). Do not edit. */\n#include <stdint.h>\n\n")
    f.write(c_array("yrp_vert_spv", words("vert.spv")) + "\n\n")
    f.write(c_array("yrp_frag_spv", words("frag.spv")) + "\n\n")
    f.write(c_array("yrp_cache_frag_spv", words("cache.spv")) + "\n\n")
    f.write(c_array("yrp_yuv_vert_spv", words("yuvv.spv")) + "\n\n")
    f.write(c_array("yrp_yuv_frag_spv", words("yuvf.spv")) + "\n")
w = words("tap.spv")
with open("Sources/YcodeVulkan/DepthTapShader.swift", "w") as f:
    f.write("// Generated by scripts/xr-depth-shaders.sh from shaders/depth_tap.comp (Ycode's own\n"
            "// GLSL, compiled with glslc). Do not edit.\n\n")
    f.write("let depthTapSPIRV: [UInt32] = [\n")
    for i in range(0, len(w), 8):
        f.write("    " + ", ".join(f"0x{x:08x}" for x in w[i:i+8]) + ",\n")
    f.write("]\n")
EOF
echo "xr-depth-shaders: done"
